import { Component, computed, input, output } from '@angular/core';

type PageItem = number | 'ellipsis';

@Component({
  selector: 'app-paginator',
  templateUrl: './paginator.component.html',
  styleUrl: './paginator.component.scss',
})
export class PaginatorComponent {
  readonly currentPage = input.required<number>();
  readonly lastPage = input.required<number>();
  readonly total = input.required<number>();
  readonly perPage = input.required<number>();
  readonly pageSizeOptions = input<number[]>([10, 25, 50]);

  readonly pageChange = output<number>();
  readonly pageSizeChange = output<number>();

  readonly safeLastPage = computed(() => Math.max(1, this.lastPage()));

  readonly safeCurrentPage = computed(() =>
    Math.min(this.currentPage(), this.safeLastPage()),
  );

  readonly isFirstPage = computed(() => this.safeCurrentPage() <= 1);

  readonly isLastPage = computed(() => this.safeCurrentPage() >= this.safeLastPage());

  readonly from = computed(() => {
    if (this.total() === 0) return 0;
    return (this.safeCurrentPage() - 1) * this.perPage() + 1;
  });

  readonly to = computed(() => {
    if (this.total() === 0) return 0;
    return Math.min(this.safeCurrentPage() * this.perPage(), this.total());
  });

  readonly rangeText = computed(() => {
    if (this.total() === 0) return 'Sin resultados';
    return `Mostrando ${this.from()}–${this.to()} de ${this.total()}`;
  });

  readonly pageItems = computed<PageItem[]>(() => {
    const last = this.safeLastPage();
    const current = this.safeCurrentPage();

    if (last <= 7) {
      return Array.from({ length: last }, (_, i) => i + 1);
    }

    const pages = new Set<number>([1, last, current]);

    if (current - 1 > 1) pages.add(current - 1);
    if (current + 1 < last) pages.add(current + 1);

    const sorted = [...pages].sort((a, b) => a - b);
    const items: PageItem[] = [];

    for (let i = 0; i < sorted.length; i++) {
      if (i > 0 && sorted[i] - sorted[i - 1] > 1) {
        items.push('ellipsis');
      }
      items.push(sorted[i]);
    }

    return items;
  });

  goToPage(page: number): void {
    if (page >= 1 && page <= this.safeLastPage() && page !== this.safeCurrentPage()) {
      this.pageChange.emit(page);
    }
  }

  previous(): void {
    if (!this.isFirstPage()) {
      this.pageChange.emit(this.safeCurrentPage() - 1);
    }
  }

  next(): void {
    if (!this.isLastPage()) {
      this.pageChange.emit(this.safeCurrentPage() + 1);
    }
  }

  onPageSizeChange(event: Event): void {
    const value = Number((event.target as HTMLSelectElement).value);
    this.pageSizeChange.emit(value);
  }
}
